async (req, res, next) => {
            const body = req.body as OSKCallCreationBody;

            try {
                await callCreationBodySchema.validateAsync(body);
            } catch (error) {
                this.logger.logError(`Invalid payload: ${error}`);
                res.status(400);
                return next(`Invalid payload: ${error}`);
            }

            const accessControlDevice: OSKAccessControlDeviceDocument | undefined =
                await OSKAccessControlDeviceController.default.get(body.callerId);
            if (accessControlDevice) {
                const body = req.body as OSKCallCreationBody;

                const callTransferList: OSKCallTransferListItem[] = await OSKCallService.getCallTransferList(
                    body.buildingId,
                    body.contactId,
                    body.creationTimestamp
                );
                if (callTransferList.length === 0) {
                    res.status(404);
                    return next('intercomTransferList not found');
                }
                const firstCallTransferListItem: OSKCallTransferListItem | undefined = callTransferList.find(
                    (item) => item.sequenceNumber === 1
                );
                if (!firstCallTransferListItem) {
                    res.status(404);
                    return next('firstCallTransferListItem not found');
                }
                // TODO: we should make it works for all callRecipients, not just the first one (CLD1-852)
                const userId = firstCallTransferListItem.callRecipients[0].callerId;
                const user: OSKUserDocument | undefined = await OSKUserController.default.get(userId);

                if (user) {
                    try {
                        const call: OSKCall = {
                            callId: body.externalCallId,
                            externalCallId: body.externalCallId,
                            callerId: body.callerId,
                            callerType: body.callerType,
                            buildingId: body.buildingId,
                            unitId: body.unitId,
                            contactId: body.contactId,
                            iceServers: body.iceServers,
                            callTransferList: [...callTransferList],
                            status: 'created',
                            events: [{ status: 'created', timestamp: body.creationTimestamp }],
                        };
                        const callId = await OSKCallController.default.create(call);
                        call.callId = callId;

                        // Extract building door name based on buildingDoorAssignment with graceful fallback
                        let displayName = 'Intercom';
                        try {
                            const doorAssignment = accessControlDevice?.buildingDoorAssignment;
                            if (doorAssignment?.buildingId && doorAssignment?.doorId) {
                                const buildingDoor = await OSKBuildingDoorController.default.get(
                                    doorAssignment.buildingId,
                                    doorAssignment.doorId
                                );
                                if (buildingDoor?.name) {
                                    displayName = buildingDoor.name;
                                }
                            }
                        } catch (error) {
                            this.logger.logError('Failed to fetch building door name for call creation', {
                                error,
                                accessControlDeviceId: body.callerId,
                            });
                        }

                        await OSKUserNotificationService.createSpecial(user.userId, {
                            type: 'userCallReceived',
                            language: user.settings.global.language,
                            data: {
                                callId: body.externalCallId,
                                callerId: body.callerId,
                                callerType: body.callerType,
                                debugCallId: call.callId,
                                recipientCallerId: user.userId,
                                iceServers: call.iceServers,
                                displayName: displayName,
                            },
                        });
                        const timestamp = new Date().toISOString();

                        try {
                            OSKCallService.updateCallTransferListStarted(call.callTransferList, timestamp);
                        } catch (error) {
                            res.status(404);
                            return next(`update callTransferList failed: ${error}`);
                        }

                        call.status = 'started';
                        call.events = [
                            { status: 'created', timestamp: body.creationTimestamp },
                            { status: 'started', timestamp },
                        ];

                        if (body.picture) {
                            try {
                                const contentType = 'image/jpg';
                                const pictureFileName = `${uuid()}.jpg`;

                                // Upload in storage
                                const imageStorageFile = storage()
                                    .bucket()
                                    .file(`calls/${call.callId}/public/callPictures/${pictureFileName}`);

                                await imageStorageFile.save(Buffer.from(body.picture, 'base64'), {
                                    contentType: contentType,
                                });

                                call.callPictureName = pictureFileName;
                            } catch (err) {
                                this.logger.logError('Error upload call picture', { err });
                            }
                        } else {
                            this.logger.logDebug('Call not have picture');
                        }

                        await OSKCallController.default.update(call.callId, call);

                        res.status(200).json(call);
                        return;
                    } catch (error) {
                        res.status(500);
                        return next(`Internal error ${error}`);
                    }
                } else {
                    res.status(404);
                    return next('Not found');
                }
            } else {
                res.status(403);
                return next('Forbiden');
            }
        }

