async (req, res, next) => {
            // this.logger.logDebug('Incoming request', { req });

            const callId = req.params.callId;
            const body = req.body as OSKCallUpdateBody;

            try {
                await callUpdateBodySchema.validateAsync(body);
            } catch (error) {
                this.logger.logError(`Invalid payload: ${error}`);
                res.status(400);
                return next(`Invalid payload: ${error}`);
            }

            const call = await OSKCallController.default.get(callId);

            if (call) {
                if ('callTransferList' in body && 'callTransferList' in call) {
                    for (const item of body.callTransferList) {
                        const correspondingItem = call.callTransferList.find(
                            (anItem) => anItem.sequenceNumber === item.sequenceNumber
                        );
                        if (!correspondingItem) {
                            this.logger.logError('Not authorized');
                            res.status(403);
                            return next('Not authorized');
                        }
                    }
                    for (const item of call.callTransferList) {
                        const correspondingItem = body.callTransferList.find(
                            (anItem) => anItem.sequenceNumber === item.sequenceNumber
                        );
                        if (!correspondingItem) {
                            this.logger.logError('Not authorized');
                            res.status(403);
                            return next('Not authorized');
                        }
                    }
                    await OSKCallController.default.update(callId, body);

                    // when call ends, creates the document in /users/ collection
                    if (['terminated', 'failed', 'cancelled'].includes(body.status)) {
                        const startTimeString = body.events.find((event) => event.status === 'created')?.timestamp;
                        const endTimeString = body.events.find((event) => event.status === body.status)?.timestamp;
                        if (!startTimeString || !endTimeString) {
                            this.logger.logError('Invalid event status');
                            res.status(400);
                            return next('Invalid event status');
                        }

                        const startDate = new Date(startTimeString);
                        const endDate = new Date(endTimeString);
                        const startTime = Timestamp.fromDate(startDate);
                        const endTime = Timestamp.fromDate(endDate);
                        const callDuration = endDate.getTime() - startDate.getTime();

                        let finalStatus: OSKCallStatus = body.status;

                        // Determine status `missed` from call
                        const callRecipientEventStatus: string[] = [];
                        body.callTransferList?.forEach((data) => {
                            data.callRecipients?.forEach((recipient) => {
                                callRecipientEventStatus.push(...(recipient.events?.map((data) => data.status) || []));
                            });
                        });
                        if (!callRecipientEventStatus.includes('didJoin')) {
                            finalStatus = 'missed';
                        }

                        // ====> Participant not receive notification
                        // https://oskey-io.atlassian.net/browse/CLD1-787
                        // Signaling status call not correctly update when participant dit not reveiced notification
                        // callRecipient status == hasBeenNotified and call status == started
                        // ===> call status must be : cancelled or terminated
                        //
                        // if (
                        //     ['created', 'started'].includes(body.status) &&
                        //     userCallTransfer?.callRecipients.at(-1)?.status === 'hasBeenNotified'
                        // ) {
                        //     finalStatus = 'missed';
                        // }

                        for (const item of body.callTransferList) {
                            for (const callRecipient of item.callRecipients) {
                                const userDocument: OSKUserCallDocument = {
                                    startTime,
                                    endTime,
                                    status: finalStatus,
                                    buildingId: body.buildingId,
                                    contactId: body.contactId,
                                    callId: body.callId,
                                    callerId: body.callerId,
                                    unitId: body.unitId,
                                    callerType: body.callerType,
                                    callDuration,
                                    activityId: callId,
                                    creationDate: Timestamp.now(),
                                };
                                if (body.callPictureName) {
                                    userDocument.callPictureName = body.callPictureName;
                                }
                                await OSKUserCallController.default.set(callRecipient.callerId, userDocument);
                                // activities flow
                                try {
                                    const activityId = callId;
                                    const enrichedData: EnrichedActivityData | null =
                                        await OSKActivityEnrichmentService.enrichAndValidateActivity({
                                            activityId,
                                            accessControlDeviceId: body.callerId,
                                            userId: callRecipient.callerId,
                                            activityType: OSKAccessControlDeviceActivityType.CALL,
                                            timestamp: endTime.toDate().toISOString(),
                                            acdType: 'intercom',
                                        });

                                    if (enrichedData && enrichedData.user) {
                                        await OSKUserActivityAggregatesService.ActivityReceivedForUser(
                                            {
                                                activityId,
                                                accessControlDeviceId: body.callerId,
                                                userId: callRecipient.callerId,
                                                activityType: OSKAccessControlDeviceActivityType.CALL,
                                                timestamp: endTime.toDate().toISOString(),
                                                acdType: 'intercom',
                                            },
                                            enrichedData,
                                            userDocument
                                        );
                                    }
                                } catch (error) {
                                    this.logger.logError('Failed to create call activity aggregate', { error });
                                    // Ne pas bloquer le flux principal si cette étape échoue
                                }
                                // --- FIN DE L'AJOUT ---
                            }
                        }
                    }
                    res.status(200).json({});
                } else {
                    this.logger.logError('Invalid payload');
                    res.status(400);
                    return next('Invalid payload');
                }
            } else {
                this.logger.logError(`Call ${callId} could not be found`);
                res.status(404);
                return next('Not found');
            }
        }

async (req, res, next) => {
            const callId = req.params.callId;
            const sequenceNumber = parseInt(req.params.sequenceNumber);

            const call: OSKCallDocument | undefined = await OSKCallController.default.get(callId);

            if (call) {
                const item = call.callTransferList.find((item) => sequenceNumber === item.sequenceNumber);
                if (item) {
                    const response: OSKCallNotificationRequestResponse = {
                        notified: [],
                        notNotified: [],
                    };
                    if (call.callerType === 'acd') {
                        let displayName = 'Intercom';
                        try {
                            const acd = await OSKAccessControlDeviceController.default.get(call.callerId);

                            // Extract building door name based on buildingDoorAssignment
                            const doorAssignment = acd?.buildingDoorAssignment;
                            if (doorAssignment?.buildingId && doorAssignment?.doorId) {
                                const buildingDoor = await OSKBuildingDoorController.default.get(
                                    doorAssignment.buildingId,
                                    doorAssignment.doorId
                                );
                                if (buildingDoor?.name) {
                                    displayName = buildingDoor.name;
                                }
                            }
                        } catch (error) {
                            this.logger.logError('Failed to fetch building door name for notification', {
                                error,
                                callerId: call.callerId,
                            });
                        }

                        for (const recipient of item.callRecipients) {
                            const user = await OSKUserController.default.get(recipient.callerId);
                            if (user) {
                                try {
                                    await OSKUserNotificationService.createSpecial(recipient.callerId, {
                                        type: 'userCallReceived',
                                        language: user.settings.global.language,
                                        collapsId: call.externalCallId,
                                        data: {
                                            callId: call.externalCallId,
                                            debugCallId: call.callId,
                                            callerId: call.callerId,
                                            callerType: call.callerType,
                                            recipientCallerId: recipient.callerId,
                                            iceServers: call.iceServers,
                                            displayName: displayName,
                                        },
                                    });
                                    response.notified = [...response.notified, recipient.callerId];
                                } catch (error) {
                                    response.notNotified = [
                                        ...response.notNotified,
                                        {
                                            callerId: recipient.callerId,
                                            error: { type: 'internal', message: `${error}` },
                                        },
                                    ];
                                }
                            }
                        }
                    }

                    if (response.notified.length === 0 && response.notNotified.length === 0) {
                        res.status(404);
                        return next('Not found');
                    } else {
                        if (call.callTransferList.find((item) => item.sequenceNumber === sequenceNumber + 1)) {
                            response.nextSequenceNumber = sequenceNumber + 1;
                        }
                        res.status(200).json(response);
                        return;
                    }
                } else {
                    this.logger.logError(`Call sequence ${callId} / ${sequenceNumber} could not be found`);
                    res.status(404);
                    return next('Not found');
                }
            } else {
                this.logger.logError(`Call ${callId} could not be found`);
                res.status(404);
                return next('Not found');
            }
        }

(item) => {
            let status: OSKCallTransferListItemStatus = 'future'; // 'next' | 'future' | 'current' | 'done' | 'cancelled'
            if (item.sequenceNumber === 1) {
                status = 'next';
            }
            return {
                callRecipients: OSKCallService.convertRecipientsFromIntercomToCall(
                    item.callRecipients,
                    creationTimestamp
                ),
                sequenceNumber: item.sequenceNumber,
                status,
                events: [{ status, timestamp: creationTimestamp }],
            };
        }

